{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "SelectableCardGroup",
    "displayName": "Selectable Card Group",
    "category": "Form Controls",
    "keywords": [
      "card",
      "selectable",
      "group",
      "radio",
      "radiogroup",
      "checkbox",
      "single choice",
      "multiple choice",
      "plan picker",
      "selection"
    ],
    "description": "A set of selectable cards with the semantics of its selection. One choice (the default) is a radio group: the cards are native radios sharing one name, so the set is one tab stop, the arrow keys move and select, and screen readers speak the position (\"2 of 3\"). Several choices are a named group of checkboxes. Each SelectableCardGroupItem is a SelectableCard whose input, name and selection come from the group.",
    "props": [
      {
        "name": "label",
        "type": "string",
        "description": "The group's visible label and accessible name.",
        "required": true
      },
      {
        "name": "selectionMode",
        "type": "'single' | 'multiple'",
        "description": "`single`: a radio group with one value. `multiple`: a group of checkboxes with any number of values.",
        "default": "'single'"
      },
      {
        "name": "value",
        "type": "string | null | ReadonlyArray<string>",
        "description": "The chosen value (`single`, `null` while none is chosen) or values (`multiple`).",
        "required": true
      },
      {
        "name": "onChange",
        "type": "(value: string) => void | (value: string[]) => void",
        "description": "Called with the chosen value (`single`) or the new list of values (`multiple`).",
        "required": true
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Hides the label visually; it still names the group.",
        "default": "false"
      },
      {
        "name": "description",
        "type": "string",
        "description": "Helper text under the label, linked to the group."
      },
      {
        "name": "htmlName",
        "type": "string",
        "description": "The name the group's value is submitted under. The radios group by a generated name. Defaults to a generated one."
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Disables every card; they stay focusable and announce disabled.",
        "default": "false"
      },
      {
        "name": "orientation",
        "type": "'horizontal' | 'vertical'",
        "description": "`horizontal` wraps the cards in rows; `vertical` stacks them.",
        "default": "'horizontal'"
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "SelectableCardGroupItem cards. Each takes a `value` and the SelectableCard props other than isSelected and onChange.",
        "required": true
      },
      {
        "name": "containerXstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for the Field box around the label, description and cards (margins, positioning, sizing). The group composes Field, so it takes no root xstyle, className or style."
      },
      {
        "name": "containerClassName",
        "type": "string",
        "description": "Class name for the Field box. Same targeting as containerXstyle."
      },
      {
        "name": "containerStyle",
        "type": "CSSProperties",
        "description": "Inline styles for the Field box. Same targeting as containerXstyle."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-selectable-card-group",
          "visualProps": [
            "orientation",
            "selectionMode"
          ]
        }
      ]
    },
    "usage": {
      "description": "Use it for a choice among a few rich options shown as cards: a plan, an appearance, a layout. One choice gives users the radio-group keyboard and the position they expect; use `multiple` when several cards can be on.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Give every card a `label` that names its option; it is the radio or checkbox name screen readers speak."
        },
        {
          "guidance": true,
          "description": "Start a single choice with a value when the product has a sensible default, so the tab stop lands on it."
        },
        {
          "guidance": false,
          "description": "Put buttons or links inside the cards; the whole card is the radio or checkbox target."
        },
        {
          "guidance": false,
          "description": "Use it for navigation or actions; use ClickableCard for those."
        }
      ]
    },
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
